<?php require 'includes/config.php';if(!isLoggedIn()){header('Location:login.php');exit;}$cart=$_SESSION['cart']??[];if(!$cart){header('Location:cart.php');exit;}$pageTitle='Checkout';$total=0;foreach($cart as $i)$total+=$i['price']*$i['qty'];$delivery=$total>=15000?0:750;$grand=$total+$delivery;if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO orders(user_id,customer_name,email,phone,address,total,status) VALUES(?,?,?,?,?,?, 'Pending')");$st->execute([$_SESSION['user']['id'],$_POST['name'],$_POST['email'],$_POST['phone'],$_POST['address'],$grand]);$oid=$pdo->lastInsertId();$it=$pdo->prepare("INSERT INTO order_items(order_id,product_id,product_name,price,qty) VALUES(?,?,?,?,?)");foreach($cart as $i)$it->execute([$oid,$i['id'],$i['name'],$i['price'],$i['qty']]);$pdo->commit();$_SESSION['cart']=[];header('Location:order_success.php?id='.$oid);exit;}include 'includes/header.php';?>
<section class="page-hero"><div class="container"><span class="eyebrow">Secure checkout</span><h1>Complete your order</h1></div></section><section class="section"><div class="container contact-grid"><form class="form-card" method="post"><h2>Delivery details</h2><div class="field"><label>Full name</label><input name="name" value="<?=e($_SESSION['user']['name'])?>" required></div><div class="field"><label>Email</label><input type="email" name="email" value="<?=e($_SESSION['user']['email'])?>" required></div><div class="field"><label>Phone</label><input name="phone" required></div><div class="field"><label>Address</label><textarea name="address" required></textarea></div><div class="field"><label>Payment</label><select><option>Cash on Delivery</option><option disabled>Card payment (demo)</option></select></div><button class="btn" style="width:100%">Place order</button></form><div class="panel"><h2>Order summary</h2><?php foreach($cart as $i):?><div class="summary-row"><span><?=e($i['name'])?> × <?=$i['qty']?></span><strong>LKR <?=number_format($i['price']*$i['qty'],2)?></strong></div><?php endforeach;?><div class="summary-row"><span>Delivery</span><strong>LKR <?=number_format($delivery,2)?></strong></div><div class="summary-row total"><span>Total</span><span>LKR <?=number_format($grand,2)?></span></div></div></div></section><?php include 'includes/footer.php';?>
